export const PLACE_INDEX: IndexedPlace[] = ROWS.map(r => ({ id: r[0], name: r[1], state: r[2], country: r[3], lat: r[4], lng: r[5], kind: r[6], search: r[7] }));

const ORDER: Record<PlaceKind, number> = { city: 0, town: 1, place: 2, district: 3, state: 4, country: 5 };

/** Ranked prefix + substring search over the bundled world/India index. */
export function searchPlaces(query: string, limit = 12): IndexedPlace[] {
  const q = query.trim().toLowerCase();
  if (!q) return [];
  const hits: Array<{ p: IndexedPlace; cls: number; nlen: number }> = [];
  for (const p of PLACE_INDEX) {
    const nm = p.name.toLowerCase();
    let cls = -1;
    if (nm === q) cls = 0;
    else if (nm.startsWith(q)) cls = 1;
    else if (p.search.startsWith(q)) cls = 2;
    else if (p.search.includes(q)) cls = 3;
    if (cls < 0) continue;
    hits.push({ p, cls, nlen: nm.length });
  }
  hits.sort((a, b) => a.cls - b.cls || a.nlen - b.nlen || ORDER[a.p.kind] - ORDER[b.p.kind] || (a.p.name < b.p.name ? -1 : 1));
  return hits.slice(0, limit).map(h => h.p);
}

export function kindLabel(k: PlaceKind): string {
  return { city: 'City', town: 'Town', place: 'Destination', district: 'District', state: 'State', country: 'Country' }[k];
}